def main() -> None:
    lines = [
        "# LIQA TODO (full product)",
        "",
        "Status: ` [ ] ` open · `[x]` done · `[~]` in progress",
        "Core law: headed Worker is the product. Headless is not a P0 SKU.",
        "",
    ]
    n = 0
    for title, items in SECTIONS:
        lines.append(f"## {title}")
        lines.append("")
        for item in items:
            n += 1
            lines.append(f"- [ ] **T{n:03d}** {item}")
        lines.append("")
    lines.append(f"_Total items: **{n}**_")
    lines.append("")
    out = Path(__file__).resolve().parents[1] / "docs" / "TODO.md"
    out.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {n} todos -> {out}")


if __name__ == "__main__":
    main()
